struct Node {
    int value;
    vector<Node*> forward; // one forward pointer per level this node participates in
    Node(int v, int level) : value(v), forward(level + 1, nullptr) {}
};

class SkipList {
    Node* head;
    int maxLevel;
    float p; // probability of promoting to the next level, typically 0.5

public:
    SkipList(int maxLvl = 16, float prob = 0.5) : maxLevel(maxLvl), p(prob) {
        head = new Node(INT_MIN, maxLevel);
    }

    int randomLevel() {
        int lvl = 0;
        while (((float) rand() / RAND_MAX) < p && lvl < maxLevel) lvl++;
        return lvl;
    }

    bool search(int target) {
        Node* curr = head;
        for (int i = maxLevel; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->value < target) {
                curr = curr->forward[i];
            }
        }
        curr = curr->forward[0];
        return curr && curr->value == target;
    }
};
